INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (132, 'hotModelagemBase', 'Mount de Modelagem em 1 ida (DRIVERS,CONTAS,CRS,CONTA_DRIVERS,EXCECOES,DRIVER_CONFIGS,CR_CONTA). Sem params.', 'SQL', 'SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''DESCRICAO'',t.DESCRICAO,''COR'',t.COR,''ATIVO'',t.ATIVO,''CRIADO_EM'',t.CRIADO_EM,''TIPO_DRIVER'',t.TIPO_DRIVER,''ORIGEM'',t.ORIGEM)) FROM DRIVERS t WHERE t.ATIVO = ''true''),JSON_ARRAY()) AS DRIVERS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CODIGO'',t.CODIGO,''NOME'',t.NOME,''TIPO'',t.TIPO,''NATUREZA'',t.NATUREZA,''ATIVO'',t.ATIVO)) FROM CONTA_CONTABIL t WHERE 1=1),JSON_ARRAY()) AS CONTAS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CODIGO'',t.CODIGO,''NOME'',t.NOME,''EMPRESA_ID'',t.EMPRESA_ID,''ATIVO'',t.ATIVO)) FROM CENTRO_RESULTADO t WHERE t.ATIVO = ''true''),JSON_ARRAY()) AS CRS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CONTA_ID'',t.CONTA_ID,''DRIVER_ID'',t.DRIVER_ID,''CRIADO_EM'',t.CRIADO_EM,''PACOTE_ID'',t.PACOTE_ID)) FROM CONTA_DRIVER t WHERE 1=1),JSON_ARRAY()) AS CONTA_DRIVERS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CR_ID'',t.CR_ID,''CONTA_ID'',t.CONTA_ID,''DRIVER_ID'',t.DRIVER_ID,''ATIVO'',t.ATIVO,''CRIADO_EM'',t.CRIADO_EM,''PACOTE_ID'',t.PACOTE_ID)) FROM CONTA_DRIVER_EXCECAO t WHERE t.ATIVO = true),JSON_ARRAY()) AS EXCECOES,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''DRIVER_ID'',x.DRIVER_ID,''QTD'',x.QTD)) FROM (SELECT DRIVER_ID, COUNT(*) AS QTD FROM DRIVER_FORMULA WHERE TIPO = ''FORMULA'' AND FORMULA IS NOT NULL AND FORMULA <> '''' GROUP BY DRIVER_ID) x),JSON_ARRAY()) AS DRIVER_CONFIGS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',cc.ID,''CR_ID'',cc.CR_ID,''CONTA_ID'',cc.CONTA_ID)) FROM CR_CONTA cc WHERE cc.ATIVO = true),JSON_ARRAY()) AS CR_CONTA', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
